      controls: { rotation: { default: true, speed: 0.3 }, speed: { default: 50, min: 0, max: 100 }, complexity: { default: 60, min: 0, max: 100 }, zoom: { default: 100, min: 50, max: 200 }, colorPicker: true, autoRevealToggle: true },
